CREATE OR REPLACE FUNCTION public.research_runtime_plan_create(a uuid, p_plan uuid, s uuid, e uuid, p_discovery uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE p research_plans; v jsonb;
